import{_ as a,o as t,c as i,a0 as o}from"./chunks/framework.CNoGN0p1.js";const c=JSON.parse('{"title":"Tutorial","description":"","frontmatter":{"prev":{"text":"Installation","link":"/setup/installation"},"next":{"text":"Input data","link":"/tutorial/data/"}},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md"}'),n={name:"tutorial/index.md"};function l(r,e,s,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h1><p>For over a decade, it has been known that a subset of individuals with a genetic (Mendelian) disease have more than one such disease (<a href="https://pubmed.ncbi.nlm.nih.gov/27959697/" target="_blank" rel="noreferrer">Posey et al., 2017</a>). This situation has been referred to in the literature as blended phenotype, dual (or multiple) genetic diagnosis, Multilocus Genomic Variation, composite phenotype, co-occurrence of diseases, comorbidity, and others. For conciseness, we will use the acronym MGD (multiple genetic diagnosis).</p><p>Phenoblend is a desktop application designed to visualize the phenotypic profile observed in individuals with MGD.</p><h1 id="using-phenoblend" tabindex="-1">Using Phenoblend <a class="header-anchor" href="#using-phenoblend" aria-label="Permalink to &quot;Using Phenoblend&quot;">​</a></h1><p>Phenoblend is a desktop application that can be run on Mac, Windows, or several types of linux. Users need to load the required data and then can visualize the phenotypic profiles.</p><ul><li><a href="./data.html">Loading HPO/HPOA data</a></li><li><a href="./input.html">Loading input data</a></li><li><a href="./visualizations.html">Visualizations</a></li><li><a href="./overlap.html">Understanding the overlap plot</a></li><li><a href="./upset.html">Understanding the upset plot</a></li><li><a href="./profile.html">Understanding the phenotype profile plot</a></li></ul><h1 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h1><p>Users should download the following phenopacket in order to follow along with the tutorial.</p><ul><li><a href="../public/PMID_15948193_proposita.json" download="NF1-PTPN11-blended-tutorial.json">Download Phenopacket</a></li></ul><div style="font-size:65%;"> The phenopacket was created based on data from <a href="https://pubmed.ncbi.nlm.nih.gov/15948193/" target="__blank">Bertola DR, et al. (2005) Neurofibromatosis-Noonan syndrome: molecular evidence of the concurrence of both disorders in a patient. <i>Am J Med Genet A</i> <b>136</b>:242-5</a></div>',10)])])}const m=a(n,[["render",l]]);export{c as __pageData,m as default};
